import { ToolDefinition } from "../types/index.js";
import { callNetsuiteRestlet } from "../utils/api.js";
import { getEnvironmentConfig } from "../utils/config.js";

export const getScriptLogsTool: ToolDefinition = {
    name: "netsuite_get_script_logs",
    description:
        "Retrieve the last 500 execution logs for a specific NetSuite script by either script ID ('scriptId', e.g., 'customscript_*', 'custevsub_*', or numeric internal ID) " +
        "or file name ('scriptFileName'), or retrieve the last 500 execution logs generated by calls to 'netsuite_run_function' when 'runFunctionLogs' is set to true.",
    meta: {
        isDestructive: false,
        requiresSdf: false
    },
    inputSchema: {
        type: "object",
        properties: {
            scriptId: {
                type: "string",
                description:
                    "Script custom ID (e.g., 'customscript_my_ue', 'custevsub_my_sub') or numeric internal ID of the NetSuite script to retrieve execution logs for. Provide either 'scriptId' or 'scriptFileName' (not both), unless 'runFunctionLogs' is true."
            },
            scriptFileName: {
                type: "string",
                description:
                    "File name (or path) of the NetSuite script to retrieve execution logs for (e.g., 'ue_salesorder.js'). Provide either 'scriptFileName' or 'scriptId' (not both), unless 'runFunctionLogs' is true."
            },
            runFunctionLogs: {
                type: "boolean",
                description:
                    "If true, retrieves the last 500 execution logs generated by calls to 'netsuite_run_function' (from the MCP Services RESTlet deployment) instead of querying by 'scriptId' or 'scriptFileName'."
            }
        }
    },
    execute: async (args: { scriptId?: string; scriptFileName?: string; runFunctionLogs?: boolean }) => {
        try {
            if (args?.runFunctionLogs) {
                const { config } = await getEnvironmentConfig();
                const payload = {
                    action: "SCRIPT_LOGS_BY_ID",
                    scriptId: config.scriptId,
                    deploymentId: config.deploymentId
                };
                const response = await callNetsuiteRestlet(payload);
                return { content: [{ type: "text", text: JSON.stringify(response, null, 2) }] };
            }

            const rawScriptId = typeof args?.scriptId === "string" ? args.scriptId.trim() : "";
            const rawFileName = typeof args?.scriptFileName === "string" ? args.scriptFileName.trim() : "";

            if (rawScriptId && rawFileName) {
                return {
                    content: [{
                        type: "text",
                        text: "Validation Error: Please provide either 'scriptId' or 'scriptFileName', not both."
                    }]
                };
            }

            if (!rawScriptId && !rawFileName) {
                return {
                    content: [{
                        type: "text",
                        text: "Validation Error: Please provide 'scriptId', 'scriptFileName', or set 'runFunctionLogs: true'."
                    }]
                };
            }

            if (rawScriptId) {
                const payload = { action: "SCRIPT_LOGS_BY_ID", scriptId: rawScriptId };
                const response = await callNetsuiteRestlet(payload);
                return { content: [{ type: "text", text: JSON.stringify(response, null, 2) }] };
            }

            const normalizedFileName = rawFileName.split(/[\\/]/).pop() || rawFileName;
            const payload = { action: "SCRIPT_LOGS", scriptFileName: normalizedFileName };
            const response = await callNetsuiteRestlet(payload);
            return { content: [{ type: "text", text: JSON.stringify(response, null, 2) }] };
        } catch (error: any) {
            return { content: [{ type: "text", text: `RESTlet Execution Error: ${error.message}` }] };
        }
    }
};
